- name: orders
  loaded_at_field: _loaded_at
  freshness:
    warn_after: {count: 12, period: hour}
    error_after: {count: 24, period: hour}

{% if is_incremental() %}
where loaded_at > (select max(loaded_at) from {{ this }})
{% endif %}

{% if is_incremental() %}
where loaded_at > (select max(loaded_at) from {{ ______ }})
{% endif %}

{%- set methods = ['credit_card', 'coupon',
                   'bank_transfer', 'gift_card'] -%}
select
    order_id,
    {%- for pm in methods %}
    sum(case when payment_method = {{ pm }} then amount else 0 end)
        as {{ pm }}_amount
    {%- if not loop.last %},{% endif %}
    {%- endfor %}
from {{ ref('stg_stripe__payments') }}
where status = 'success'
group by order_id

- name: orders
  _______________: _loaded_at
  freshness:
    warn_after: {count: 12, period: hour}
    error_after: {count: 24, period: hour}

with customers as (
    select * from {{ source('jaffle_shop', 'customers') }}
),
orders as (
    select * from {{ ref('fct_orders') }}
)

unit_tests:
  - name: test_dim_customers_lifetime_value
    model: dim_customers
    given:
      - input: ref('stg_jaffle_shop__customers')
        rows:
          - {customer_id: 1, first_name: Ana, email: ana@x.com}
          - {customer_id: 2, first_name: Bo, email: bo@x.com}
      - input: ref('fct_orders')
        rows:
          - {order_id: 10, customer_id: 1, order_date: 2025-03-01, amount: 20.0}
          - {order_id: 11, customer_id: 1, order_date: 2025-04-01, amount: 5.5}
    expect:
      rows:
        - {customer_id: 1, number_of_orders: 2, lifetime_value: 25.5}
        - {customer_id: 2, number_of_orders: 0, lifetime_value: 0}

{% macro cents_to_dollars(column_name, scale=2) -%}
    round({{ column_name }} / 100, {{ scale }})
{%- endmacro %}

{% test is_positive(model, column_name) %}
select *
from {{ model }}
where {{ column_name }} < 0
{% endtest %}
